package com.thedirepack.constructioncalc.core.model

import com.thedirepack.constructioncalc.core.math.Rational
import com.thedirepack.constructioncalc.core.measure.Dimension
import com.thedirepack.constructioncalc.core.measure.Quantity
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Tests for the cross-tool data bus (ResultValue, ValueKind, StoredQuantity).
 * Verifies that values generated by one tool can be seamlessly read, converted, and consumed by another.
 */
class InteroperabilityTest {

    @Test
    fun measurementResultsExchangedBetweenToolsLosslessly() {
        // Foot-Inch produces a length of 7' 11 1/2" (95.5 inches = 191/2)
        val exactLength = Quantity.inches(Rational.of(191, 2))
        val publishedResult = ResultValue.of(
            key = "result",
            label = "Foot-Inch result",
            quantity = exactLength,
            text = "7' 11 1/2\"",
        )

        assertEquals(ValueKind.LENGTH, publishedResult.kind)
        assertEquals("191/2", publishedResult.exact)
        assertEquals("7' 11 1/2\"", publishedResult.text)

        // Voltage Drop picks up this ResultValue and converts to feet
        val consumedQuantity = publishedResult.toQuantity()
        assertNotNull(consumedQuantity)
        assertEquals(Dimension.LENGTH, consumedQuantity!!.dimension)
        assertEquals(Rational.of(191, 2), consumedQuantity.value)

        // StoredQuantity serialization round-trip across project storage
        val stored = consumedQuantity.stored()
        val decoded = StoredQuantity(stored.exact, stored.dimension).toQuantity()
        assertEquals(consumedQuantity, decoded)
    }

    @Test
    fun nonMeasureKindsKeepExactNumericsWithoutCreatingQuantity() {
        // Voltage Drop publishes percent drop and load voltage
        val percentDrop = ResultValue.number("percent_drop", "% drop", ValueKind.PERCENT, Rational.of(3, 1), "3.0 %")
        val voltage = ResultValue.number("load_voltage", "Voltage at load", ValueKind.VOLTAGE, 116.4, "116.4 V")
        val textResult = ResultValue.text("min_size", "Min wire", "3 AWG Cu")

        assertEquals(ValueKind.PERCENT, percentDrop.kind)
        assertEquals(Rational.of(3, 1), percentDrop.rational)
        assertNull("Percent drop should not convert to a spatial Quantity", percentDrop.toQuantity())

        assertEquals(ValueKind.VOLTAGE, voltage.kind)
        assertNotNull(voltage.rational)
        assertNull(voltage.toQuantity())

        assertEquals(ValueKind.TEXT, textResult.kind)
        assertNull(textResult.exact)
        assertNull(textResult.rational)
        assertNull(textResult.toQuantity())
    }

    @Test
    fun allResultsIndexedProperlyAcrossRunsInProject() {
        val project = Project.create("Industrial Warehouse", now = 1000L, firstRunName = "Feeder 1")
        val run1Id = project.runs.first().id

        val item1 = ProjectItem(
            toolId = "voltagedrop",
            title = "Feeder VD",
            createdAt = 1000L,
            results = listOf(
                ResultValue.number("voltage_drop", "Voltage drop", ValueKind.VOLTAGE, 4.2, "4.2 V"),
                ResultValue.number("percent_drop", "Percent drop", ValueKind.PERCENT, 1.75, "1.75 %"),
            ),
        )

        val run2 = Run(name = "Conduit Branch 1")
        val item2 = ProjectItem(
            toolId = "conduitfill",
            title = "Branch Fill",
            createdAt = 1100L,
            results = listOf(
                ResultValue.number("fill_percent", "Conduit fill", ValueKind.PERCENT, 38.5, "38.5%"),
            ),
        )

        val updated = project.addItem(run1Id, item1, 1000L)
            .addRun(run2, 1100L)
            .addItem(run2.id, item2, 1100L)

        val allResults = updated.allResults()
        assertEquals(3, allResults.size)
        // Check sorting: newest item first (item2 createdAt 1100L)
        assertEquals("Branch Fill", allResults.first().item.title)
        assertEquals(ValueKind.PERCENT, allResults.first().value.kind)
        assertEquals("conduitfill", allResults.first().item.toolId)
    }
}
